      const previous = new Set((state.data.models || []).map(m=>m.id));
      await api('/api/models/demo',{projectId:state.project});
      b.modelId = (state.data.models || []).find(m=>!previous.has(m.id) && m.projectId === state.project)?.id || (state.data.models || []).find(m=>m.projectId === state.project && m.demo)?.id || '';
      b.suggestionsFor = ''; b.elementId = null; b.issueId = ''; b.storey = ''; b.status = ''; b.priority = ''; b.query = ''; state.page = 'bim'; state.modal = null;
